/* Optional diagnostic: set WORDPADCUSTOM_PROFILE_STARTUP=1 before launching.
 * No disk I/O and no timing checkpoints when the variable is absent.
 * Reports are written to %%TEMP%%\\WordPadCustom_Startup_Timing.txt. */
#define RWP_STARTUP_POINT_CAPACITY 24
typedef struct
{
    const char *description;
    LARGE_INTEGER tick;
} RWP_STARTUP_POINT;
static BOOL rwpStartupProfileEnabled;
static LARGE_INTEGER rwpStartupStart, rwpStartupFrequency;
static RWP_STARTUP_POINT rwpStartupPoints[RWP_STARTUP_POINT_CAPACITY];
static int rwpStartupPointCount;

static void rwp_startup_profile_begin(void)
{
    WCHAR value[4];
    DWORD length = GetEnvironmentVariableW(L"WORDPADCUSTOM_PROFILE_STARTUP",
                                           value, sizeof(value)/sizeof(value[0]));
    if (length != 1 || value[0] != L'1' ||
        !QueryPerformanceFrequency(&rwpStartupFrequency) ||
        !QueryPerformanceCounter(&rwpStartupStart))
        return;
    rwpStartupProfileEnabled = TRUE;
}

static void rwp_startup_profile_mark(const char *description)
{
    RWP_STARTUP_POINT *point;
    if (!rwpStartupProfileEnabled ||
        rwpStartupPointCount >= RWP_STARTUP_POINT_CAPACITY)
        return;
    point = &rwpStartupPoints[rwpStartupPointCount++];
    point->description = description;
    QueryPerformanceCounter(&point->tick);
}

static void rwp_startup_profile_write(void)
{
    WCHAR path[MAX_PATH];
    HANDLE file;
    LARGE_INTEGER previous;
    DWORD pathLen, written;
    int i;
    static const char heading[] = "WordPad(Custom) startup timings (milliseconds)\r\n"
                                  "Elapsed: since WinMain entry; Phase: since previous checkpoint.\r\n";
    if (!rwpStartupProfileEnabled || !rwpStartupFrequency.QuadPart) return;
    pathLen = GetTempPathW(MAX_PATH, path);
    if (!pathLen || pathLen >= MAX_PATH ||
        pathLen + lstrlenW(L"WordPadCustom_Startup_Timing.txt") >= MAX_PATH)
        return;
    lstrcatW(path, L"WordPadCustom_Startup_Timing.txt");
    file = CreateFileW(path, GENERIC_WRITE, FILE_SHARE_READ, NULL, CREATE_ALWAYS,
                       FILE_ATTRIBUTE_NORMAL, NULL);
    if (file == INVALID_HANDLE_VALUE) return;
    WriteFile(file, heading, sizeof(heading)-1, &written, NULL);
    previous = rwpStartupStart;
    for (i = 0; i < rwpStartupPointCount; ++i)
    {
        char line[256];
        LONGLONG elapsedUs = (rwpStartupPoints[i].tick.QuadPart -
                              rwpStartupStart.QuadPart) * 1000000 /
                              rwpStartupFrequency.QuadPart;
        LONGLONG phaseUs = (rwpStartupPoints[i].tick.QuadPart -
                            previous.QuadPart) * 1000000 /
                            rwpStartupFrequency.QuadPart;
        int length = wsprintfA(line, "%s: elapsed %ld.%03ld, phase %ld.%03ld\r\n",
                              rwpStartupPoints[i].description,
                              (long)(elapsedUs / 1000), (long)(elapsedUs % 1000),
                              (long)(phaseUs / 1000), (long)(phaseUs % 1000));
        if (length > 0 && length < (int)sizeof(line))
            WriteFile(file, line, (DWORD)length, &written, NULL);
        previous = rwpStartupPoints[i].tick;
    }
    CloseHandle(file);
}


