static void rwp_redraw_text_color_button(void)
{
    HWND rebar, toolbar;
    if (!hMainWnd) return;
    rebar = GetDlgItem(hMainWnd, IDC_REBAR);
    toolbar = rebar ? GetDlgItem(rebar, IDC_FORMATBAR) : NULL;
    if (toolbar) InvalidateRect(toolbar, NULL, FALSE);
}

static void rwp_record_applied_text_color(COLORREF color, BOOL automatic)
{
    rwpLastTextColor = color;
    rwpLastTextColorAutomatic = automatic;
    rwpLastTextColorValid = TRUE;
    rwp_redraw_text_color_button();
}

/* Merely setting the insertion point's future typing color is not the
 * same as applying a color to any text in the document. */
static void rwp_record_selected_text_color(COLORREF color, BOOL automatic)
{
    CHARRANGE selection;
    if (!hEditorWnd) return;
    SendMessageW(hEditorWnd, EM_EXGETSEL, 0, (LPARAM)&selection);
    if (selection.cpMax > selection.cpMin)
        rwp_record_applied_text_color(color, automatic);
}

static void rwp_record_applied_highlight(COLORREF color, BOOL remove)
{
    rwpLastHighlightColor = color;
    rwpLastHighlightRemove = remove;
    rwpLastHighlightColorValid = TRUE;
    rwp_redraw_text_color_button();
}

static void rwp_record_selected_highlight(COLORREF color, BOOL remove)
{
    CHARRANGE selected;
    if (!hEditorWnd) return;
    SendMessageW(hEditorWnd, EM_EXGETSEL, 0, (LPARAM)&selected);
    if (selected.cpMax > selected.cpMin)
        rwp_record_applied_highlight(color, remove);
}

static void rwp_reset_applied_text_color(void)
{
    rwpLastTextColorValid = FALSE;
    rwpLastTextColorAutomatic = FALSE;
    rwpLastPickedTextColorValid = FALSE;
    rwpLastHighlightColorValid = FALSE;
    rwp_redraw_text_color_button();
}

