static void rwp_cloud_reset(void)
{
    ++rwpCloudDocumentSerial;
    ZeroMemory(&rwpCloudDoc, sizeof(rwpCloudDoc));
    rwpCloudDoc.maxVersions = 30;
    rwpCloudDoc.retentionDays = 7;
    rwpCloudDoc.periodicSaveSeconds = RWP_CLOUD_PERIODIC_DEFAULT_SECONDS;
    rwpCloudPeriodicLastTick = GetTickCount();
    rwpCloudMetadataUnsafe = FALSE;
    /* Stop the previous document's periodic timer before loading the next. */
    rwp_cloud_periodic_sync_timer();
}


