/* Ask other WordPad windows whether they already have a given document open.
 * WM_COPYDATA safely transfers the path between processes; this is intentionally
 * per-DOCUMENT rather than a single-instance restriction for the application. */
#define RWP_OPEN_DOC_QUERY 0x52575044UL
#define RWP_WM_RELAYOUT (WM_APP + 52)
#define RWP_WM_COMPLETE_EXPLORER_DROP (WM_APP + 53)
#define RWP_WM_CLOUD_FINISH_HIDDEN_CLOSE (WM_APP + 54)

/* A close with an automatic upload pending hides the editor instead of
 * destroying its owner (and with it the upload completion callbacks).
 * Reopening the same document cancels this deferred close. */
static BOOL rwpCloudCloseWhenIdle = FALSE;
static BOOL rwpCloudCloseWasMaximized = FALSE;

static void rwp_cloud_cancel_hidden_close(void)
{
    if (!rwpCloudCloseWhenIdle) return;
    rwpCloudCloseWhenIdle = FALSE;
    if (!IsWindow(hMainWnd)) return;
    ShowWindow(hMainWnd, rwpCloudCloseWasMaximized ? SW_SHOWMAXIMIZED : SW_SHOW);
    if (IsIconic(hMainWnd)) ShowWindow(hMainWnd, SW_RESTORE);
    rwp_backup_begin_interval();
    rwp_cloud_periodic_reset_clock();
    SetForegroundWindow(hMainWnd);
}

